from records.api import normalize_payload
from records.normalizer import normalize_record
from tests.fixtures import V1_RECORD, V2_RECORD


def test_normalize_record_v1():
    assert normalize_record(V1_RECORD) == {"id": "user-1", "name": "Ada"}


def test_normalize_payload_wraps_record():
    assert normalize_payload({"record": V1_RECORD}) == {
        "record": {"id": "user-1", "name": "Ada"}
    }


def test_normalize_record_accepts_display_name_alias():
    assert normalize_record(V2_RECORD) == {"id": "user-2", "name": "Grace"}
